import React, { useState } from "react";
import "./Home.css";

export default function Home() {
  const [search, setSearch] = useState("");

  const professionals = [
    { name: "Ravi Kumar", job: "Electrician" },
    { name: "Sita Reddy", job: "Plumber" },
    { name: "Manoj Verma", job: "Carpenter" },
    { name: "Akhil Sharma", job: "Painter" },
    { name: "Priya Nair", job: "Cleaner" },
  ];

  const filtered = professionals.filter((p) =>
    p.job.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="home-container">
      <h1 className="welcome">Welcome to HirePro</h1>

      {/* Search Bar */}
      <input
        type="text"
        className="search-bar"
        placeholder="Search professionals (Plumber, Painter, etc)"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />

      {/* Professionals List */}
      <div className="pro-list">
        {filtered.length > 0 ? (
          filtered.map((p, index) => (
            <div className="pro-card" key={index}>
              <h3>{p.name}</h3>
              <p>{p.job}</p>
            </div>
          ))
        ) : (
          <p className="no-result">No professionals found</p>
        )}
      </div>
    </div>
  );
}
